    for user in cfg.get("users", []):
        if not isinstance(user, dict):
            continue
        assigned = user.get("mountTemplates", [])
        if not isinstance(assigned, list) or template_name not in assigned:
            continue
        _, errors = resolve_mountpoint_records(cfg, user)
        if errors:
            return False
    return True


